"""Run the original (or mine with -m) on commands; print each reply (elements: one element per line).
usage: o.py [-m] [-p project] [-s script] [-k keys] [-o save] cmd...
"""
import subprocess, sys, os, json, tempfile, shutil
ORIG = '/workspace/executable'
MINE = '/workspace/.claude/worktrees/agent-abc3090a833c0c2dd/target/release/bimcraft-cli'
a = sys.argv[1:]
exe = ORIG; proj = None; only = None; script = None; save = None
while a and a[0].startswith('-'):
    if a[0] == '-m': exe = MINE; a = a[1:]
    elif a[0] == '-p': proj = os.path.abspath(a[1]); a = a[2:]
    elif a[0] == '-s': script = os.path.abspath(a[1]); a = a[2:]
    elif a[0] == '-k': only = set(a[1].split(',')); a = a[2:]
    elif a[0] == '-o': save = os.path.abspath(a[1]); a = a[2:]
    else: break
d = tempfile.mkdtemp(prefix='o')
args = [exe, 'run']
if proj: args.append(proj)
if script: args += ['--script', script]
for c in a: args += ['--cmd', c]
if save: args += ['--save', save]
p = subprocess.run(args, cwd=d, capture_output=True, timeout=300)
shutil.rmtree(d)
err = p.stderr.decode('utf-8', 'replace').strip()
for line in p.stdout.decode('utf-8', 'replace').strip().split('\n'):
    try:
        v = json.loads(line)
    except Exception:
        print(line); continue
    if isinstance(v, dict) and 'elements' in v and 'count' in v:
        print('count', v.get('count'), 'returned', v.get('returned'))
        for e in v['elements']:
            if only:
                e = {k: x for k, x in e.items() if k in only or k in ('id', 'category')}
            print(json.dumps(e, ensure_ascii=False))
    else:
        print(json.dumps(v, ensure_ascii=False))
if err: print('ERR', err)
print('exit', p.returncode)

