import json, math, sys, itertools
proj = json.load(open(sys.argv[1]))
outs = []
for f in sys.argv[2:]:
    for l in open(f):
        if '"category": "door"' in l or '"category": "window"' in l:
            outs.append(json.loads(l))
els = proj['elements']
byguid = {e['guid']: e for e in els.values()}

def centre_r(a, b, t, cm, rm):
    dx, dy = b[0] - a[0], b[1] - a[1]
    c = math.hypot(dx, dy)
    mx, my = (a[0] + b[0]) / 2, (a[1] + b[1]) / 2
    s = 1 if t > 0 else -1
    r1 = c / 2 / math.sin(abs(t) / 2)
    nx, ny = -dy / c, dx / c
    if cm == 'cos':
        h = r1 * math.cos(t / 2)
        cx, cy = mx + nx * h * s, my + ny * h * s
    elif cm == 'tan':
        d = (c / 2) / math.tan(t / 2)
        cx, cy = mx + nx * d, my + ny * d
    elif cm == 'tan2':
        d = (c / 2) / math.tan(t / 2)
        cx, cy = mx - dy * d / c, my + dx * d / c
    elif cm == 'tan3':
        k = 0.5 / math.tan(t / 2)
        cx, cy = mx - dy * k, my + dx * k
    elif cm == 'sqrt':
        h = math.sqrt(max(r1 * r1 - c * c / 4, 0))
        if abs(t) > math.pi: h = -h
        cx, cy = mx + nx * h * s, my + ny * h * s
    elif cm == 'tangent':
        cd = math.atan2(dy, dx)
        th = cd - t / 2
        cx = a[0] - s * r1 * math.sin(th)
        cy = a[1] + s * r1 * math.cos(th)
    if rm == 'r1':
        r = r1
    else:
        r = math.hypot(a[0] - cx, a[1] - cy)
    return cx, cy, r

def point(a, b, arc, off, cm, rm, pm, qm):
    t = math.radians(arc)
    cx, cy, r = centre_r(a, b, t, cm, rm)
    s = 1 if t > 0 else -1
    L = r * abs(t)
    if pm == 'off/r':
        phi = s * off / r
    elif pm == 'frac':
        phi = t * (off / L)
    elif pm == 'frac6m':
        L6 = round(L * 1e6) * 1e-6
        phi = t * (off / L6)
    elif pm == 'frac6d':
        L6 = round(L * 1e6) / 1e6
        phi = t * (off / L6)
    elif pm == 'tf':
        phi = t * off / L
    a0 = math.atan2(a[1] - cy, a[0] - cx)
    if qm == 'polar':
        ang = a0 + phi
        return (cx + r * math.cos(ang), cy + r * math.sin(ang))
    elif qm == 'rot':
        vx, vy = a[0] - cx, a[1] - cy
        co, si = math.cos(phi), math.sin(phi)
        return (cx + vx * co - vy * si, cy + vx * si + vy * co)
    elif qm == 'polar2':
        ang = a0 + phi
        return (cx + math.cos(ang) * r, cy + math.sin(ang) * r)

combos = list(itertools.product(['cos', 'tan', 'tan2', 'tan3', 'sqrt', 'tangent'], ['r1', 'r2'], ['off/r', 'frac', 'frac6m', 'frac6d', 'tf'], ['polar', 'rot']))
score = {c: 0 for c in combos}
tot = 0
for o in outs:
    w = byguid[o['host']]
    if not w.get('arc'):
        continue
    tot += 1
    want = tuple(o['at'])
    for c in combos:
        try:
            got = point(w['start'], w['end'], w['arc'], o['offset'], *c)
        except Exception:
            continue
        if got == want:
            score[c] += 1
best = sorted(score.items(), key=lambda kv: -kv[1])[:12]
print(tot)
for c, s in best:
    print(s, c)

