"""Evaluate many number formulas with the original, in families of <= 60 parameters."""
import json, subprocess, tempfile, shutil

BASE = [
    {"name": "A", "kind": "length", "value": 1200},
    {"name": "B", "kind": "length", "value": 500},
]

def evaluate(exprs, base=BASE, exe='/workspace/executable'):
    out = {}
    chunk = 60 - len(base)
    cmds = []
    names = []
    for c in range(0, len(exprs), chunk):
        part = exprs[c:c + chunk]
        params = list(base)
        for i, e in enumerate(part):
            params.append({"name": "F%d" % (c + i), "kind": "number", "formula": e})
        name = 'FX%d' % c
        fam = {"name": name, "category": "generic", "parameters": params, "types": {"T": {}}}
        cmds += ['--cmd', 'family ' + json.dumps(fam), '--cmd', 'family {"name":"%s"}' % name]
        names.append(name)
    dd = tempfile.mkdtemp()
    p = subprocess.run([exe, 'run'] + cmds, cwd=dd, capture_output=True, timeout=300)
    shutil.rmtree(dd)
    err = p.stderr.decode()
    if err:
        print('ERR', err[:2000])
    vals = {}
    for line in p.stdout.decode().strip().split('\n'):
        try:
            v = json.loads(line)
        except Exception:
            continue
        if 'values' in v:
            vals.update(v['values']['T'])
    return [vals.get('F%d' % i) for i in range(len(exprs))]

