    # end-based direction: from e towards s negated
    gx = s[0] - e[0]; gy = s[1] - e[1]
    Lg = math.sqrt(gx * gx + gy * gy); ig = 1 / Lg
    r['neg'] = (s[0] - (gx * ig) * o, s[1] - (gy * ig) * o)
