// reads lines: sx sy ex ey off atx aty ; prints scores of candidates
use std::io::Read;
fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let rows: Vec<Vec<f64>> = s
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| l.split_whitespace().map(|t| t.parse::<f64>().unwrap()).collect())
        .collect();
    type C = fn(f64, f64, f64, f64, f64) -> (f64, f64);
    let cands: Vec<(&str, C)> = vec![
        ("hypot div", |sx, sy, fx, fy, o| { let l = fx.hypot(fy); (sx + fx / l * o, sy + fy / l * o) }),
        ("hypot inv", |sx, sy, fx, fy, o| { let l = fx.hypot(fy); let i = 1.0 / l; (sx + fx * i * o, sy + fy * i * o) }),
        ("hypot t", |sx, sy, fx, fy, o| { let l = fx.hypot(fy); let t = o / l; (sx + fx * t, sy + fy * t) }),
        ("sqrt inv", |sx, sy, fx, fy, o| { let l = (fx * fx + fy * fy).sqrt(); let i = 1.0 / l; (sx + fx * i * o, sy + fy * i * o) }),
        ("sqrt div", |sx, sy, fx, fy, o| { let l = (fx * fx + fy * fy).sqrt(); (sx + fx / l * o, sy + fy / l * o) }),
        ("fmax inv", |sx, sy, fx, fy, o| { let l = fx.mul_add(fx, fy * fy).sqrt(); let i = 1.0 / l; (sx + fx * i * o, sy + fy * i * o) }),
        ("fmay inv", |sx, sy, fx, fy, o| { let l = fy.mul_add(fy, fx * fx).sqrt(); let i = 1.0 / l; (sx + fx * i * o, sy + fy * i * o) }),
        ("atan2", |sx, sy, fx, fy, o| { let a = fy.atan2(fx); (sx + a.cos() * o, sy + a.sin() * o) }),
        ("atan2 sincos", |sx, sy, fx, fy, o| { let a = fy.atan2(fx); let (sn, cs) = a.sin_cos(); (sx + cs * o, sy + sn * o) }),
        ("hypot t2", |sx, sy, fx, fy, o| { let l = fx.hypot(fy); let t = o / l; (sx + t * fx, sy + t * fy) }),
    ];
    for (name, f) in cands {
        let (mut nx, mut ny) = (0, 0);
        for r in &rows {
            let (x, y) = f(r[0], r[1], r[2] - r[0], r[3] - r[1], r[4]);
            if x == r[5] { nx += 1; }
            if y == r[6] { ny += 1; }
        }
        println!("{:<14} x {} y {} of {}", name, nx, ny, rows.len());
    }
}

