use std::io::Read;

fn centre(sx: f64, sy: f64, ex: f64, ey: f64, t: f64, cm: usize, lm: usize) -> (f64, f64, f64) {
    let dx = ex - sx;
    let dy = ey - sy;
    let c = match lm {
        0 => dx.hypot(dy),
        _ => (dx * dx + dy * dy).sqrt(),
    };
    let mx = (sx + ex) / 2.0;
    let my = (sy + ey) / 2.0;
    let half = c / 2.0;
    let r = half / (t.abs() / 2.0).sin();
    let sg = if t > 0.0 { 1.0 } else { -1.0 };
    match cm {
        0 => {
            // mid + n * r cos(t/2) * sg, n = left normal unit (via inv)
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let h = r * (t / 2.0).cos();
            (mx + nx * h * sg, my + ny * h * sg, r)
        }
        1 => {
            let (nx, ny) = (-dy / c, dx / c);
            let h = r * (t / 2.0).cos();
            (mx + nx * h * sg, my + ny * h * sg, r)
        }
        2 => {
            // d = half / tan(t/2) signed
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let d = half / (t / 2.0).tan();
            (mx + nx * d, my + ny * d, r)
        }
        3 => {
            let (nx, ny) = (-dy / c, dx / c);
            let d = half / (t / 2.0).tan();
            (mx + nx * d, my + ny * d, r)
        }
        4 => {
            // radius from hypot of start - centre
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let d = half / (t / 2.0).tan();
            let cx = mx + nx * d;
            let cy = my + ny * d;
            let rr = (sx - cx).hypot(sy - cy);
            (cx, cy, rr)
        }
        5 => {
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let h = r * (t / 2.0).cos();
            let cx = mx + nx * h * sg;
            let cy = my + ny * h * sg;
            let rr = (sx - cx).hypot(sy - cy);
            (cx, cy, rr)
        }
        6 => {
            // centre from start along the start tangent's normal
            let th = dy.atan2(dx) - t / 2.0;
            let cx = sx - sg * r * th.sin();
            let cy = sy + sg * r * th.cos();
            (cx, cy, r)
        }
        7 => {
            // d via r*cos(t/2) with signed r: r_s = half / sin(t/2)
            let rs = half / (t / 2.0).sin();
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let h = rs * (t / 2.0).cos();
            (mx + nx * h, my + ny * h, rs.abs())
        }
        _ => {
            // mid computed as s + d/2
            let mx = sx + dx / 2.0;
            let my = sy + dy / 2.0;
            let inv = 1.0 / c;
            let (nx, ny) = (-dy * inv, dx * inv);
            let d = half / (t / 2.0).tan();
            (mx + nx * d, my + ny * d, r)
        }
    }
}

fn main() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let rows: Vec<Vec<f64>> = s
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| l.split_whitespace().map(|t| t.parse::<f64>().unwrap()).collect())
        .collect();
    let mut res = Vec::new();
    for cm in 0..9 {
        for lm in 0..2 {
            for pm in 0..4 {
                for tm in 0..2 {
                    let (mut nx, mut ny) = (0, 0);
                    for r in &rows {
                        let t = if tm == 0 { r[4].to_radians() } else { r[4] * std::f64::consts::PI / 180.0 };
                        let (cx, cy, rad) = centre(r[0], r[1], r[2], r[3], t, cm, lm);
                        let sg = if t > 0.0 { 1.0 } else { -1.0 };
                        let off = r[5];
                        let a0 = (r[1] - cy).atan2(r[0] - cx);
                        let (x, y) = match pm {
                            0 => {
                                let a = a0 + sg * off / rad;
                                (cx + rad * a.cos(), cy + rad * a.sin())
                            }
                            1 => {
                                let len = rad * t.abs();
                                let a = a0 + t * (off / len);
                                (cx + rad * a.cos(), cy + rad * a.sin())
                            }
                            2 => {
                                let phi = sg * off / rad;
                                let (vx, vy) = (r[0] - cx, r[1] - cy);
                                let (sn, cs) = phi.sin_cos();
                                (cx + vx * cs - vy * sn, cy + vx * sn + vy * cs)
                            }
                            _ => {
                                let a = a0 + off / rad * sg;
                                (cx + a.cos() * rad, cy + a.sin() * rad)
                            }
                        };
                        if x == r[6] { nx += 1; }
                        if y == r[7] { ny += 1; }
                    }
                    res.push((nx + ny, nx, ny, cm, lm, pm, tm));
                }
            }
        }
    }
    res.sort();
    res.reverse();
    for r in res.iter().take(12) {
        println!("total {} x {} y {} | centre {} len {} point {} rad {} | of {}", r.0, r.1, r.2, r.3, r.4, r.5, r.6, rows.len());
    }
}

